    {"tipo":"vf","enunciado":"Don Bosco gritaba y pegaba a los muchachos.","correta":false,"explicacao":"Educaba con cariño y paciencia."},
    {"tipo":"multipla","enunciado":"¿Qué lugar creó Don Bosco para los muchachos?","opcoes":["El Oratorio","Una cárcel","Una tienda de dulces"],"correta":0,"explicacao":"En el Oratorio había juegos, clases y oración."},
    {"tipo":"vf","enunciado":"Muchos muchachos de Don Bosco no tenían casa ni familia.","correta":true,"explicacao":"Él los recibía como un padre."},
    {"tipo":"multipla","enunciado":"¿Cómo se llama la familia de sacerdotes y religiosas que empezó Don Bosco?","opcoes":["Los Salesianos","Los Bomberos","Los Scouts"],"correta":0,"explicacao":"Los Salesianos cuidan de jóvenes en el mundo entero."},
    {"tipo":"vf","enunciado":"Un alumno de Don Bosco, Domingo Savio, también llegó a ser santo.","correta":true,"explicacao":"Domingo decía que ser santo es estar siempre alegre."},
    {"tipo":"ordenar","enunciado":"Arma la frase:","blocos":["Don Bosco","amaba","a los jóvenes"],"explicacao":"Decía que bastaba ser joven para que él te quisiera."},
    {"tipo":"vf","enunciado":"Don Bosco enseñaba oficios a los muchachos.","correta":true,"explicacao":"Aprendían a ser zapateros, sastres, carpinteros y mucho más."},
    {"tipo":"multipla","enunciado":"¿Qué palabra va con Don Bosco?","opcoes":["Alegría","Tristeza","Pereza"],"correta":0,"explicacao":"Don Bosco era alegre y repartía alegría."}
