    {"tipo":"vf","enunciado":"La Madre Teresa aprendió otros idiomas para hablar con la gente.","correta":true,"explicacao":"Aprendió a hablar bengalí e hindi."},
    {"tipo":"multipla","enunciado":"¿A quién amaba la Madre Teresa por encima de todo?","opcoes":["A Jesús","Al dinero","A la fama"],"correta":0,"explicacao":"Su amor por Jesús la hacía amar a los pobres."}
